def has_zero_sum_permutation(Y, m):
    elements = sorted(list(Y))
    memo = {}

    def search(current_sum, used_mask):
        state = (current_sum, used_mask)
        if state in memo:
            return memo[state]

        if used_mask == (1 << (m - 1)) - 1:
            return current_sum == 0

        j = bin(used_mask).count('1') + 1

        for i in range(m - 1):
            if not (used_mask & (1 << i)):
                # If there are multiple elements with the same value,
                # we only need to try one of them at this position.
                if i > 0 and elements[i] == elements[i-1] and not (used_mask & (1 << (i - 1))):
                    continue
                if search((current_sum + j * elements[i]) % m, used_mask | (1 << i)):
                    memo[state] = True
                    return True

        memo[state] = False
        return False

    return search(0, 0)

