def is_m_valid(m):
    for X in itertools.combinations_with_replacement(range(m), m):
        if sum(X) % m != 0:
            unique_Y = set()
            for i in range(m):
                Y = list(X)
                Y.pop(i)
                unique_Y.add(tuple(sorted(Y)))

