def find_counterexample(m):
    # To speed up, let's only check multisets that are "likely" to be counterexamples.
    # A counterexample X for m=6 was (1, 1, 1, 1, 1, 3).
    # A counterexample X for m=10 was (1, 1, 1, 1, 1, 1, 1, 1, 1, 3).
    # These are of the form {1, 1, ..., 1, 3} where there are m-1 ones.
    # Let's check this first.

    # Try {1, 1, ..., 1, k} for k in {0, ..., m-1}
    for k in range(m):
        X = [1] * (m - 1) + [k]
        if sum(X) % m != 0:
            unique_Y = set()
            for i in range(m):
                Y = list(X)
                Y.pop(i)
                unique_Y.add(tuple(sorted(Y)))

            all_none = True
            for Y_tuple in unique_Y:
                if has_zero_sum_permutation(Y_tuple, m):
                    all_none = False
                    break

            if all_none:
                return X

    # If that didn't work, try another simple form.
    # Maybe {0, 0, ..., 0, k} ? No, that's {0, 0, ..., 0, k}, sum is k, Y is {0, 0, ..., 0}, sum is 0.

    # Let's try {1, 1, ..., 1, 1, k} ? No.
    # Let's try {1, 2, 3, ..., m-1, k} ?
    for k in range(m):
        X = list(range(1, m)) + [k]
        # Wait, m-1 elements are 1, 2, ..., m-1. So X has m elements.
        # But some of them might be the same if k is in {1, ..., m-1}.
        # Let's just use the list as is.
        if sum(X) % m != 0:
            unique_Y = set()
            for i in range(m):
                Y = list(X)
                Y.pop(i)
                unique_Y.add(tuple(sorted(Y)))

            all_none = True
            for Y_tuple in unique_Y:
                if has_zero_sum_permutation(Y_tuple, m):
                    all_none = False
                    break

            if all_none:
                return X

    return None

