from itertools import combinations_with_replacement

def check_m(m):
    # We need to check all multisets of size m with elements from {0, ..., m-1}
    # For each multiset, check if (sum(X) % m == 0) or (exists permutation s.t. sum(j * x_sigma(j)) % m == 0)

    # To optimize, we can use a recursive function with memoization to check the permutation condition
    memo = {}

    def can_form_zero(idx, current_sum, counts):
        state = (idx, current_sum, counts)
        if state in memo:
            return memo[state]

        if idx == m + 1:
            return current_sum == 0

        # Try all residues that still have counts > 0
        for r in range(m):
            if counts[r] > 0:
                new_counts = list(counts)
                new_counts[r] -= 1
                if can_form_zero(idx + 1, (current_sum + idx * r) % m, tuple(new_counts)):
                    memo[state] = True
                    return True

        memo[state] = False
        return False

    # Instead of all multisets, we can iterate through them
    for multiset in combinations_with_replacement(range(m), m):
        s = sum(multiset)
        if s % m == 0:
            continue

        memo = {}
        counts = [0] * m
        for x in multiset:
            counts[x] += 1

        if not can_form_zero(1, 0, tuple(counts)):
            return False
    return True

