        state = (idx, current_sum, counts)
        if state in memo:
            return memo[state]
        if idx == m + 1:
            return current_sum == 0
        for r in range(m):
            if counts[r] > 0:
                new_counts = list(counts)
                new_counts[r] -= 1
                if can_form_zero(idx + 1, (current_sum + idx * r) % m, tuple(new_counts), memo):
                    memo[state] = True
                    return True
        memo[state] = False
        return False

    for multiset in combinations_with_replacement(range(m), m):
        s = sum(multiset)
        if s % m == 0:
            continue

        memo = {}
        counts = [0] * m
        for x in multiset:
            counts[x] += 1

        if not can_form_zero(1, 0, tuple(counts), memo):
