    def has_permutation_sum_zero(counts, m):
        # idx is the current position in the permutation (from 1 to m)
        # current_sum is the current sum modulo m
        # counts is the current counts of each residue
        def solve(idx, current_sum, current_counts):
            if idx == m + 1:
                return current_sum == 0
            state = (idx, current_sum, current_counts)
            if state in memo:
                return memo[state]

            for r in range(m):
                if current_counts[r] > 0:
                    new_counts = list(current_counts)
                    new_counts[r] -= 1
                    if solve(idx + 1, (current_sum + idx * r) % m, tuple(new_counts)):
                        memo[state] = True
                        return True
            memo[state] = False
            return False

