def check_all_multisets(m):
    def get_all_multisets(m):
        def backtrack(index, current_sum, current_counts):
            if index == m:
                if current_sum == m:
                    yield tuple(current_counts)
                return
            for count in range(m - current_sum + 1):
                current_counts[index] = count
                yield from backtrack(index + 1, current_sum + count, current_counts)
        yield from backtrack(0, 0, [0] * m)

    for counts in get_all_multisets(m):
        total_sum = sum(i * counts[i] for i in range(m))
        if total_sum % m == 0:
            continue

        memo = {}
        def solve(pos, current_s, current_counts):
            state = (pos, current_s, current_counts)
            if state in memo: return memo[state]
            if pos == m + 1: return current_s == 0

            for res in range(m):
                if current_counts[res] > 0:
                    new_counts = list(current_counts)
                    new_counts[res] -= 1
                    if solve(pos + 1, (current_s + pos * res) % m, tuple(new_counts)):
                        memo[state] = True
                        return True
            memo[state] = False
            return False

        if not solve(1, 0, counts):
            return False 
    return True

