    # sum c_i = m
    for counts in itertools.product(range(m+1), repeat=m):
        if sum(counts) == m:
            X = []
            for i in range(m):
                X.extend([i] * counts[i])
            if sum(X) % m != 0:
                X_list.append(X)

    for X in X_list:
        dp = [[set() for _ in range(m)] for _ in range(m + 1)]
        dp[0][0].add(0)
        for i in range(1, m + 1):
            coeff = i
            for s in range(m):
                for mask in dp[i-1][s]:
                    for j in range(m):
                        if not (mask & (1 << j)):
                            new_s = (s + coeff * X[j]) % m
                            dp[i][new_s].add(mask | (1 << j))
        if not dp[m][0]:
            return True # Counterexample found
    return False

