from itertools import combinations_with_replacement

def get_possible_sums(x, m):
    # x is a tuple of m residues
    # dp[mask] = set of possible sums using indices 1..popcount(mask)
    # and elements of x at positions in mask.
    n = len(x)
    dp = [set() for _ in range(1 << n)]
    dp[0].add(0)

    for mask in range(1 << n):
        # Current number of elements used
        k = bin(mask).count('1')
        if k == n:
            continue

        # We want to assign an unused element of x to the next position k+1
        # Wait, the positions are 1, 2, ..., m.
        # Let's say we assign an element x_j where j is not in mask
        # to position k+1.
        for j in range(n):
            if not (mask & (1 << j)):
                new_mask = mask | (1 << j)
                for s in dp[mask]:
                    dp[new_mask].add((s + (k + 1) * x[j]) % m)

    return dp[(1 << n) - 1]

def is_m_valid(m):
    # Check all multisets of size m from {0, ..., m-1}
    # A multiset is a counterexample if its sum is not 0 mod m
    # and its possible sums (under all permutations) do not include 0 mod m.
    for x in combinations_with_replacement(range(m), m):
        if sum(x) % m == 0:
            continue

        sums = get_possible_sums(x, m)
        if 0 not in sums:
            return False # Found a counterexample
    return True

