def get_possible_sums(x, m):
    n = len(x)
    dp = [set() for _ in range(1 << n)]
    dp[0].add(0)

    for mask in range(1 << n):
        k = bin(mask).count('1')
        if k == n:
            continue

        for j in range(n):
            if not (mask & (1 << j)):
                new_mask = mask | (1 << j)
                for s in dp[mask]:
                    dp[new_mask].add((s + (k + 1) * x[j]) % m)

    return dp[(1 << n) - 1]

