import itertools

def solve():
    results = []
    for m in range(2, 15):
        # Generate all multisets of size m from {0, 1, ..., m-1}
        # A multiset can be represented as a sorted tuple
        found_counterexample = False
        # To iterate over multisets, we can use combinations with replacement
        for multiset in itertools.combinations_with_replacement(range(m), m):
            if sum(multiset) % m == 0:
                continue

            # Check if any permutation gives sum(j * x_sigma(j)) % m == 0
            # Actually, we want to see if ALL permutations are non-zero mod m
            # or if there exists any permutation that is zero mod m.
            # The condition is: "at least one of the following holds: sum(x_i) == 0 OR exists sigma s.t. sum(j * x_sigma(j)) == 0"
            # So we want to find a multiset where sum(x_i) != 0 AND for all sigma, sum(j * x_sigma(j)) != 0

            # Since the multiset might have repeated elements, we use set(itertools.permutations)
            possible_sums = set()
            for p in itertools.permutations(multiset):
                s = 0
                for j, val in enumerate(p, 1):
                    s += j * val
                possible_sums.add(s % m)

            if 0 not in possible_sums:
                found_counterexample = True
                break

        if found_counterexample:
            results.append((m, False)) # False means fails the condition
        else:
            results.append((m, True)) # True means satisfies the condition
    return results

print(solve())

import itertools

def check_m_simple(m):
    for multiset in itertools.combinations_with_replacement(range(m), m):
        if sum(multiset) % m == 0:
            continue

        dp = [0] * (1 << m)
        dp[0] = 1
        for mask in range(1 << m):
            if dp[mask] == 0: continue
            i = bin(mask).count('1') + 1
            for j in range(m):
                if not (mask & (1 << j)):
                    new_mask = mask | (1 << j)
                    shift = (i * multiset[j]) % m
                    new_bits = (dp[mask] << shift)
                    dp[new_mask] |= (new_bits & ((1 << m) - 1)) | (new_bits >> m)

        if not (dp[(1 << m) - 1] & 1):
            return False # Counterexample found
    return True

